spawn.example:
const wagon = kcds.world.Cart.spawn('wagon_b_covered', new kcds.math.Vector3(100, 200, 10));
wagon.maxSpeed = 5;

// Refuse a second driver.
kcds.core.Events.on('cartEntering', (cart, player, seat) => {
  return seat !== 'driver' || cart.driver === null;
});

spawn.exampleCs:
var wagon = Cart.Spawn("wagon_b_covered", new Vector3(100, 200, 10));
wagon.MaxSpeed = 5;

// Refuse a second driver.
Events.On("cartEntering", object? (Cart cart, Player player, JsValue seat) =>
{
    return seat.AsString() != "driver" || cart.Driver == null;
});

all.example:
for (const cart of kcds.world.Cart.all()) {
  console.info(`${cart.blueprint} at ${cart.position}`);
}

all.exampleCs:
foreach (var cart in Cart.All())
{
    Log.Info($"{cart.Blueprint} at {cart.Position}");
}

driver.example:
if (wagon.driver) {
  kcds.core.Chat.sendToPlayer(wagon.driver, 'Slow down at the bridge.');
}

driver.exampleCs:
if (wagon.Driver != null)
{
    Chat.SendToPlayer(wagon.Driver, "Slow down at the bridge.");
}

